; Cosmo Tank (U) - Atlus sound driver (Tsukasa Masuko), ROM bank 4 $4000-$7FFF
; generated by tools/gen_ct.py; rebuilds the bank byte-exact (RGBDS 0.9.1)

INCLUDE "cosmotank_sound.inc"

SECTION "Sound driver", ROMX[$4000], BANK[4]


; SndInit: APU on, every channel silenced (NRx2 = $08, NRx4 = $80), NR50 = $77, NR10 = NR51 = 0,
; all 8 track flags cleared. Called by the game (bank 0 $161B) and by sound id 0 (and $80).
SndInit::
	ld a, $80                         ; 4000
	ldh [rNR52], a                    ; 4002
	ldh [rNR30], a                    ; 4004
	swap a                            ; 4006
	ldh [rNR12], a                    ; 4008
	ldh [rNR22], a                    ; 400A
	ldh [rNR32], a                    ; 400C
	ldh [rNR42], a                    ; 400E
	swap a                            ; 4010
	ldh [rNR14], a                    ; 4012
	ldh [rNR24], a                    ; 4014
	ldh [rNR34], a                    ; 4016
	ldh [rNR44], a                    ; 4018
	ld a, $77                         ; 401A
	ldh [rNR50], a                    ; 401C
	xor a                             ; 401E
	ldh [rNR10], a                    ; 401F
	ldh [rNR51], a                    ; 4021
	ld de, $0010                      ; 4023
	ld hl, wTracks                    ; 4026
	ld b, $08                         ; 4029
SndInit_ClearLoop:
	ld [hl], a                        ; 402B
	add hl, de                        ; 402C
	dec b                             ; 402D
	jr nz, SndInit_ClearLoop          ; 402E
	ret                               ; 4030

; SndStartQueued: start at most one queued id per frame (the last one queued).
; Header = {track, pointer-1} until $FF. Track 4-7 (SFX) set bit 7 (muted) on track - 4.
; flags = (flags | 1) & $81, timer = 1, atten = fine = transpose = 0.
SndStartQueued:
	ld hl, wSndQueueCount             ; 4031
	ld a, [hl]                        ; 4034
	and a                             ; 4035
	ret z                             ; 4036
	dec a                             ; 4037
	ld [hl], a                        ; 4038
	inc a                             ; 4039
	add a, l                          ; 403A
	ld l, a                           ; 403B
	ld a, [hl]                        ; 403C
	add a, a                          ; 403D
	jr z, SndInit                     ; 403E
	ld de, SoundTable                 ; 4040
	ld h, $00                         ; 4043
	ld l, a                           ; 4045
	add hl, de                        ; 4046
	ld e, [hl]                        ; 4047
	inc hl                            ; 4048
	ld d, [hl]                        ; 4049
	ld h, HIGH(wTracks)               ; 404A
	ld b, HIGH(wTracks)               ; 404C
SndStart_TrackLoop:
	ld a, [de]                        ; 404E
	inc a                             ; 404F
	ret z                             ; 4050
	dec a                             ; 4051
	swap a                            ; 4052
	ld l, a                           ; 4054
	cp $40                            ; 4055
	jr c, SndStart_SetTrack           ; 4057
	sub $40                           ; 4059
	ld c, a                           ; 405B
	ld a, [bc]                        ; 405C
	or $80                            ; 405D
	ld [bc], a                        ; 405F
SndStart_SetTrack:
	set 0, [hl]                       ; 4060
	ld a, $81                         ; 4062
	and [hl]                          ; 4064
	ld [hl], a                        ; 4065
	inc l                             ; 4066
	ld [hl], $01                      ; 4067
	xor a                             ; 4069
	set 2, l                          ; 406A
	ld [hl], a                        ; 406C
	inc l                             ; 406D
	ld [hl], a                        ; 406E
	inc l                             ; 406F
	ld [hl], a                        ; 4070
	inc l                             ; 4071
	inc de                            ; 4072
	ld a, [de]                        ; 4073
	ld [hl], a                        ; 4074
	inc l                             ; 4075
	inc de                            ; 4076
	ld a, [de]                        ; 4077
	ld [hl], a                        ; 4078
	inc de                            ; 4079
	jr SndStart_TrackLoop             ; 407A

; SndUpdate: once per frame (VBlank, bank 0 $160D). Tracks 7..0, then SndStartQueued.
; Per active track: timer--; at 0 read events. Otherwise envelope count--; at 0 next pair:
; NRx2 = max(vol - atten, 0) and NRx4 = period hi (trigger), unless muted.
; BUG: the new volume goes to wTrackVol + [wCurTrack], which is stale here.
SndUpdate::
	ld b, $08                         ; 407C
SndUpdate_NextTrackH:
	ld h, HIGH(wTracks)               ; 407E
SndUpdate_NextTrack:
	dec b                             ; 4080
	bit 7, b                          ; 4081
	jp nz, SndStartQueued             ; 4083
	ld l, b                           ; 4086
	swap l                            ; 4087
	ld a, [hl]                        ; 4089
	bit 0, a                          ; 408A
	jr z, SndUpdate_NextTrackH        ; 408C
	inc l                             ; 408E
	dec [hl]                          ; 408F
	jr z, SndReadEvents               ; 4090
	inc l                             ; 4092
	dec [hl]                          ; 4093
	jr nz, SndUpdate_NextTrack        ; 4094
	inc l                             ; 4096
	ld e, [hl]                        ; 4097
	inc l                             ; 4098
	ld d, [hl]                        ; 4099
	inc de                            ; 409A
	ld a, [de]                        ; 409B
	ld c, a                           ; 409C
	inc de                            ; 409D
	ld a, [de]                        ; 409E
	inc l                             ; 409F
	sub [hl]                          ; 40A0
	jr nc, SndEnvStep_VolOk           ; 40A1
	xor a                             ; 40A3
SndEnvStep_VolOk:
	dec l                             ; 40A4
	ld [hl], d                        ; 40A5
	dec l                             ; 40A6
	ld [hl], e                        ; 40A7
	dec l                             ; 40A8
	ld [hl], c                        ; 40A9
	ld c, a                           ; 40AA
	ld de, wTrackVol                  ; 40AB
	ld a, [wCurTrack]                 ; 40AE
	add a, e                          ; 40B1
	ld e, a                           ; 40B2
	ld a, c                           ; 40B3
	ld [de], a                        ; 40B4
	dec l                             ; 40B5
	dec l                             ; 40B6
	bit 7, [hl]                       ; 40B7
	jr nz, SndUpdate_NextTrack        ; 40B9
	push hl                           ; 40BB
	ld hl, RegTable                   ; 40BC
	ld a, b                           ; 40BF
	add a, a                          ; 40C0
	add a, l                          ; 40C1
	ld l, a                           ; 40C2
	ld a, $00                         ; 40C3
	adc a, h                          ; 40C5
	ld h, a                           ; 40C6
	ld a, c                           ; 40C7
	ld c, [hl]                        ; 40C8
	ldh [c], a                        ; 40C9
	inc hl                            ; 40CA
	ld c, [hl]                        ; 40CB
	pop hl                            ; 40CC
	ld a, $0D                         ; 40CD
	or l                              ; 40CF
	ld l, a                           ; 40D0
	ld a, [hl]                        ; 40D1
	ldh [c], a                        ; 40D2
	jr SndUpdate_NextTrack            ; 40D3

; SndReadEvents: read until a note, rest or end.
; $00-$53 note, $54 rest, $80-$BF length, $C0-$DF pan, $E0-$FF commands (CmdTable).
SndReadEvents:
	ld a, b                           ; 40D5
	ld [wCurTrack], a                 ; 40D6
	dec l                             ; 40D9
	set 3, l                          ; 40DA
	ld e, [hl]                        ; 40DC
	inc l                             ; 40DD
	ld d, [hl]                        ; 40DE
SndNextEvent:
	inc de                            ; 40DF
SndReadEvent:
	ld a, [de]                        ; 40E0
	bit 7, a                          ; 40E1
	jr z, EvNote                      ; 40E3
	bit 6, a                          ; 40E5
	jr z, EvLength                    ; 40E7
	bit 5, a                          ; 40E9
	jr z, EvPan                       ; 40EB
	push hl                           ; 40ED
	ld hl, CmdTable                   ; 40EE
	and $0F                           ; 40F1
	add a, a                          ; 40F3
	ld c, a                           ; 40F4
	ld b, $00                         ; 40F5
	add hl, bc                        ; 40F7
	ld b, [hl]                        ; 40F8
	inc hl                            ; 40F9
	ld h, [hl]                        ; 40FA
	ld l, b                           ; 40FB
	jp hl                             ; 40FC
EvLength:
	push hl                           ; 40FD
	res 7, a                          ; 40FE
	ld c, a                           ; 4100
	ld b, $00                         ; 4101
	ld hl, LengthTable                ; 4103
	add hl, bc                        ; 4106
	ld a, [hl]                        ; 4107
	pop hl                            ; 4108
	inc l                             ; 4109
	ld [hl], a                        ; 410A
	dec l                             ; 410B
	jr SndNextEvent                   ; 410C
EvPan:
	and $1F                           ; 410E
	ld b, a                           ; 4110
	ld a, [wCurTrack]                 ; 4111
	and $03                           ; 4114
	add a, b                          ; 4116
	push hl                           ; 4117
	ld hl, PanTable                   ; 4118
	add a, l                          ; 411B
	ld l, a                           ; 411C
	ld a, $00                         ; 411D
