	ld h, a                           ; 4120
	ld a, [hl]                        ; 4121
	ld hl, wTrackPan                  ; 4122
	ld b, a                           ; 4125
	ld a, [wCurTrack]                 ; 4126
	add a, l                          ; 4129
	ld l, a                           ; 412A
	ld [hl], b                        ; 412B
	pop hl                            ; 412C
	jr SndNextEvent                   ; 412D

; EvRest: wTrackVol = 8, flags bit 1; unless muted, clear the track's NR51 bits.
EvRest:
	push hl                           ; 412F
	ld hl, wTrackVol                  ; 4130
	ld a, [wCurTrack]                 ; 4133
	add a, l                          ; 4136
	ld l, a                           ; 4137
	ld a, $08                         ; 4138
	ld [hl], a                        ; 413A
	pop hl                            ; 413B
	ld a, [wCurTrack]                 ; 413C
	ld b, a                           ; 413F
	res 3, l                          ; 4140
	set 1, [hl]                       ; 4142
	bit 7, [hl]                       ; 4144
	jp nz, SndUpdate_NextTrack        ; 4146
	ld a, b                           ; 4149
	ld hl, wTrackPan                  ; 414A
	add a, l                          ; 414D
	ld l, a                           ; 414E
	ld a, [hl]                        ; 414F
	cpl                               ; 4150
	ld c, a                           ; 4151
	ldh a, [rNR51]                    ; 4152
	and c                             ; 4154
	swap c                            ; 4155
	and c                             ; 4157
	ldh [rNR51], a                    ; 4158
	jp SndUpdate_NextTrackH           ; 415A

; EvNote: timer = length. Period = Periods[note + transpose] + fine; trigger bit unless
; it is a CH3 track and NR52 says CH3 is still on. Envelope restarts at its first pair.
; Unless muted: NRx2, NRx1, NR51, NRx3, NRx4.
EvNote:
	inc l                             ; 415D
	ld c, [hl]                        ; 415E
	res 3, l                          ; 415F
	dec l                             ; 4161
	ld [hl], c                        ; 4162
	set 3, l                          ; 4163
	ld [hl], d                        ; 4165
	dec l                             ; 4166
	ld [hl], e                        ; 4167
	cp $54                            ; 4168
	jr z, EvRest                      ; 416A
	ld c, a                           ; 416C
	ld a, [wCurTrack]                 ; 416D
	and $03                           ; 4170
