	ld c, l                           ; 417A
	ld b, h                           ; 417B
	add a, a                          ; 417C
	ld e, a                           ; 417D
	ld d, $00                         ; 417E
	ld hl, Periods                    ; 4180
	add hl, de                        ; 4183
	ld e, [hl]                        ; 4184
	inc hl                            ; 4185
	ld d, [hl]                        ; 4186
	dec c                             ; 4187
	ld a, [bc]                        ; 4188
	ld l, a                           ; 4189
	ld h, $00                         ; 418A
	add hl, de                        ; 418C
	ld a, [wCurTrack]                 ; 418D
	and $03                           ; 4190
	cp $02                            ; 4192
	jr nz, EvNote_Trigger             ; 4194
	ldh a, [rNR52]                    ; 4196
	bit 2, a                          ; 4198
	jr nz, EvNote_StorePeriod         ; 419A
EvNote_Trigger:
	ld a, $80                         ; 419C
	or h                              ; 419E
	ld h, a                           ; 419F
EvNote_StorePeriod:
	set 3, c                          ; 41A0
	dec c                             ; 41A2
	ld a, h                           ; 41A3
	ld [bc], a                        ; 41A4
	dec c                             ; 41A5
	ld a, l                           ; 41A6
	ld [bc], a                        ; 41A7
	push hl                           ; 41A8
	inc c                             ; 41A9
	ld l, c                           ; 41AA
	ld h, b                           ; 41AB
	inc c                             ; 41AC
	res 3, l                          ; 41AD
	ld a, [bc]                        ; 41AF
	ld e, a                           ; 41B0
	inc c                             ; 41B1
	ld a, [bc]                        ; 41B2
	ld d, a                           ; 41B3
	ld a, [de]                        ; 41B4
	ld c, a                           ; 41B5
	inc de                            ; 41B6
	ld a, [de]                        ; 41B7
	sub [hl]                          ; 41B8
	jr nc, EvNote_VolOk               ; 41B9
	xor a                             ; 41BB
EvNote_VolOk:
	dec l                             ; 41BC
	ld [hl], d                        ; 41BD
	dec l                             ; 41BE
	ld [hl], e                        ; 41BF
	dec l                             ; 41C0
	ld [hl], c                        ; 41C1
	ld c, a                           ; 41C2
	ld de, wTrackVol                  ; 41C3
	ld a, [wCurTrack]                 ; 41C6
	add a, e                          ; 41C9
	ld e, a                           ; 41CA
	ld a, c                           ; 41CB
	ld [de], a                        ; 41CC
	dec l                             ; 41CD
	dec l                             ; 41CE
	bit 7, [hl]                       ; 41CF
	jr nz, EvNote_Muted               ; 41D1
	push hl                           ; 41D3
	ld hl, RegTable                   ; 41D4
	ld c, a                           ; 41D7
	ld a, [wCurTrack]                 ; 41D8
	add a, a                          ; 41DB
	add a, l                          ; 41DC
	ld l, a                           ; 41DD
	ld a, $00                         ; 41DE
	adc a, h                          ; 41E0
	ld h, a                           ; 41E1
	ld a, c                           ; 41E2
	ld c, [hl]                        ; 41E3
	ldh [c], a                        ; 41E4
	dec c                             ; 41E5
	pop de                            ; 41E6
	ld a, $0B                         ; 41E7
	or e                              ; 41E9
	ld e, a                           ; 41EA
	ld a, [de]                        ; 41EB
	ldh [c], a                        ; 41EC
	inc hl                            ; 41ED
	ld c, [hl]                        ; 41EE
	ld hl, wTrackPan                  ; 41EF
	ld a, [wCurTrack]                 ; 41F2
	add a, l                          ; 41F5
	ld l, a                           ; 41F6
	ld a, [hl]                        ; 41F7
	ld b, a                           ; 41F8
	cpl                               ; 41F9
	ld e, a                           ; 41FA
	ldh a, [rNR51]                    ; 41FB
	and e                             ; 41FD
	swap e                            ; 41FE
