; EvNoise: NR43 = note byte with its nibbles swapped; no transpose. NR42, NR51, NR43, NR44 = $80.
EvNoise:
	set 2, l                          ; 4215
	swap c                            ; 4217
	ld [hl], c                        ; 4219
	inc l                             ; 421A
	ld [hl], $80                      ; 421B
	inc l                             ; 421D
	ld e, [hl]                        ; 421E
