	dw CmdDuty                   ; $1: duty
	dw CmdAtten                  ; $2: atten
	dw CmdTranspose              ; $3: transpose
	dw CmdLoopStart              ; $4: loop_start
	dw CmdLoopEnd                ; $5: loop_end
	dw CmdCall                   ; $6: call
