; LoadWave(hl): NR32 = 0, NR30 = 0, NR34 = $80, 16 bytes to wave RAM, NR30 = $80.
LoadWave:
	xor a                             ; 43AD
	ldh [rNR32], a                    ; 43AE
	ldh [rNR30], a                    ; 43B0
	ld a, $80                         ; 43B2
	ldh [rNR34], a                    ; 43B4
