	inc c                             ; 43BC
	dec b                             ; 43BD
	jr nz, LoadWave_Loop              ; 43BE
	ld a, $80                         ; 43C0
	ldh [rNR30], a                    ; 43C2
	ld a, [wCurTrack]                 ; 43C4
	ret                               ; 43C7

; CmdEnd ($FD/$FF): track off. Music track: silence its channel unless muted.
; SFX track: unmute track - 4; if that music track is still active restore NR10 (CH1),
